def f(inputs):
    res = []
    for (N, M, compute, program) in inputs:
        if N == 0 and M == 0:
            break
        computations = {f'{x} {y}': v for (x, y, v) in compute}
        variable = {'x': 0.0, 'y': 0.0}
        instr_counter = {'x': 0, 'y': 0}
        for idx in range(M):
            x, y, vx, vy = program[idx]
            delta = max(abs(vx), abs(vy))
            num_steps = int(abs(delta))
            for _ in range(num_steps):
                variable['x'] += vx / delta
                variable['y'] += vy / delta
                if (key := f'{variable["x"]} {variable["y"]}') in computations:
                    if computations[key] > 0:
                        variable['x'] += computations[key]
                        instr_counter['x'] += 1
                    else:
                        variable['y'] -= computations[key]
                        instr_counter['y'] += 1
            if f'{int(x)} {int(y)}' in computations:
                remain_x, remain_y = variable['x'] - int(x), variable['y'] - int(y)
                delta_x, delta_y = 0.0, 0.0
                if vx!= 0:
                    delta_x = remain_x/vx
                if vy!= 0:
                    delta_y = remain_y/vy
                if abs(delta_x - delta_y) < 1e-6:
                    variable['x'], variable['y'] = x+vx*delta_x, y+vy*delta_y
                else:
                    ultimately_ran_into = (
                        (vx == 0, remain_y*(instr_counter['y']+1) >= 0, abs(remain_y) <= 1),
                        (vy == 0, remain_x*(instr_counter['x']+1) >= 0, abs(remain_x) <= 1)
                    )[instr_counter['y'] <= instr_counter['x']]
                    if ultimately_ran_into[0]: 
                        variable['y'] = y if ultimately_ran_into[1] else None
                    else:
                        variable['x'] = x if ultimately_ran_into[1] else None
        res.append((variable['x'], variable['y']))
    return res

